-- Generated from CHANGELOG.md by tools/gen-news.js. Edit CHANGELOG.md, not this file.
local _, ns = ...
ns.NEWS = {
  { version = "1.6.8", date = "2026-11-17", items = { "A home base you picked keeps the quests you carry for it after a /reload or login. They used to drop off the route, so green quests in your log for that zone got no stops (Stranglethorn: The Second Rebellion, Some Assembly Required).", "Logging in or reloading while on a flight, the card works out your step before it holds it for the flight. It used to grab the plan's next step and keep it the whole way (a trip to the Badlands on a Stranglethorn home base).", "Starting partway through your plan, the card no longer sends you to hand in a quest whose objective isn't done yet (Buy 10 Heavy Leather, Collect 4 Fresh Manure): the hand-in waits, and a follow-up the game won't offer until it's handed in says \"Needs ... handed in first\".", "A trip on the card now says what to do now: the leg you're on is the title (\"Fly to Westfall\", \"Run to Thorgrum Borrelson\", \"Take the boat to Menethil Harbor\"), with where the trip ends under it (\"then on to Stranglethorn Vale\"). It used to say \"Travel to Stranglethorn Vale\" over a numbered list of every leg. On a long trip the next leg shows dimmed; all of them are under the new \"?\" button.", "A flight path to pick up where you stand is its own short line on the card (\"Get the flight path from Lanie Reed first\"), not a clause at the end of the leg.", "A trip that leaves your zone says what it's for in one line (\"For Pearl Diving and 6 more quests at your level\").", "New \"?\" button on the card's header: click it to see why the card sends you there, for example \"Looks odd, but it's the fastest way: doing it now saves a trip back later (~8 min)\" or \"Short hop worth it: 2 hand-ins in Stormwind for ~3k XP, back in about 4 min\". It uses the minutes or XP the route worked out when it has them, and the trip's legs in full." } },
  { version = "1.6.7", date = "2026-11-16", items = { "The card no longer sends you for battleground quests: Darkspear Islands Clash, Conflict at Darkspear Islands, Fight for Warsong Gulch, Concerted Efforts and the other quests whose Marks of Honor come only from PvP matches. The built-in plans still list them, and the card now passes over their pick-up, objective and hand-in. A level 38 on the gnome warlock plan was sent across Stormwind to the Brigadier General for one. If you already have one in your log, the quest log check says it's a battleground quest, and the card takes you to its hand-in once it's finished.", "The last leg of a trip now names who you're going to (\"Walk to Angus Stern\"), not the city you just flew into (\"Ride to Stormwind\" right after landing in Stormwind).", "A flight leg reads \"Fly to Stormwind City\" when the leg before it takes you to the flight master, and \"Fly from Gretchen Mayberry to Stormwind City\" otherwise. It used to read \"Fly to Stormwind City (Gretchen Mayberry)\", as if she stood in Stormwind.", "Level 60: the card celebrates (\"Level 60 - you made it!\") and your route is done, whatever quests the plan had left. It no longer works out the route for a 60. \"Finish my quests\" on the card routes the quests you still hold - their objectives and hand-ins, nothing new picked up - and clicking it again, or the house button, goes back. Zone and dungeon routes you pick at 60 still run. Finishing your plan below 60 offers your next home bases instead of a bare \"Route complete\"." } },
  { version = "1.6.6", date = "2026-11-16", items = { "\"Change home base\" is now a house button with the card's other controls (shown when you hover the card). As a text button on the card's bottom line it sat under those controls." } },
  { version = "1.6.5", date = "2026-11-16", items = { "Trying the addon partway through levelling now starts you where you stand. A character levelling in the Barrens was sent through Orgrimmar, the zeppelin and the Undercity to Silverpine while the Barrens still had quests for them.", "The flight paths you already have are now guessed from the quests you've handed in near them, until you open a flight master's map (Forever's world map doesn't say which ones you know). The card used to send you to pick up a flight path you already had. Opening any flight master's map corrects the guesses.", "A flight path to pick up where you stand now reads \"before you go, get the ... flight path from ... nearby\" instead of sounding like an errand to another town.", "The card no longer tells you to hand in a quest whose objectives aren't done (Preventative Measures at 0/12 Rog'mar Trainees): it shows the objective first.", "After the card let go of a quest from earlier in your plan, it no longer stays on a step that's already done.", "Walking no longer plans the trip to the step on the card again every second: only once you've moved a little way (20-50 yards), the step changed or you learned a flight path. That took up to 3 ms out of one frame a second.", "The route window opens about twice as fast (at level 12, 77 ms down to 38), and with less memory churn: it works out each step once instead of three times, and the check for skipped chains no longer makes throwaway data for every step.", "Standing in a zone your plan comes to only after another whole zone, the card no longer starts that zone's quests early and then sends you off with them half done. In Duskwood at 24 with the plan going to the Wetlands first, it took up the Duskwood quests you could do, flew you to the Wetlands with them in your log and brought you back for the rest. It now goes to the Wetlands and does Duskwood after, in one go. A short errand first (a hand-in in Stormwind) still waits until you've done the quests where you are.", "Taking up a quest from earlier in your plan no longer brings back a training stop or a flight the plan had already passed, which made the card switch to the flight out while you stood still (Reading Room in Stormwind).", "Fixed an error when landing from a flight while the game had no position for you yet.", "The card no longer shows a step that is already done after it offered a quest from earlier in your plan whose follow-up comes later (Return to Verner, then A Baying of Gnolls).", "Picking a zone in Where to? no longer freezes the game for a moment at high levels.", "Accepting quests for you never takes an escort quest: an escort starts at once and fails if you're not ready, so the quest window stays open for you.", "Looting a corpse no longer makes the game hitch while you're on a kill or collect step and not Well Fed: the food check used to read the tooltip of every item in your bags after every loot. It now reads only food, and each food's tooltip only once.", "With the quest log check or the side trips window open, a kill or a loot redraws it once instead of two or three times.", "A kill, a loot or a quest log update asks the game about each quest in your log once instead of three times. With 20 quests in your log that is about 30 calls per kill instead of 65.", "On a book or collectible step, looting other items no longer rebuilds the route each time. It updates when the step's own item arrives.", "The card no longer shows a step that is already done after it offered a quest from earlier in your plan: that quest is shown as an extra while you do it, and your place in the plan stays where it was (a level 19 joining Darkshore saw For Love Eternal as done).", "A quest from earlier in your plan that the card offered stays on the card as a step to do while you walk to it (it could turn \"done\" on the way).", "The card no longer offers a quest from earlier in your plan that the game won't give you anyway, such as a breadcrumb to a quest you already have (Raven Hill with Worgen in the Woods done).", "Where to? offers each zone's route for your level. At 28 it offered Hillsbrad's route for level 22, whose quests you had done, and picking it left the card empty.", "A zone you pick whose own quests are all done still takes the quests you carry there: the card flies you there and has you hand them in, instead of showing nothing.", "Where to? opens faster again, and asks the game about fewer quests when it does.", "Where to? no longer offers a zone that has nothing for you: pick-ups it never hands in, or a gray quest waiting on an earlier one. A zone offered for hand-ins counts their XP instead of reading \"0 XP\".", "After you pick a zone, a side quest in your log only gets stops in that zone. Picking Thousand Needles no longer sent you to Stonetalon first for a Shredding Machines objective.", "With your quest log nearly full, a quest giver right beside you is no longer passed over for a flight out. The card used to plan more of the plan's pick-ups than your log had room for, and then gave up on the quest next to you.", "Picking a zone for the one quest you carry there no longer leaves the card empty. That quest is no longer skipped as \"not worth the trip\" when it's the last thing on the route.", "Skipping a quest, or saying you're not doing it, now also takes the rest of its chain off your route. The card used to keep showing the next part's pick-up, which the game never offers without the part you skipped (Samophlange in the Barrens).", "A quest 5 or more levels above you (red in your quest log) waits until you're within 4 levels of it, like a quest that needs a level. Behind the plan's levels, the card used to hand you red quests from further along the plan (Worth Its Weight in Gold, level 36, at 31). Deliveries, with nothing to fight, are still picked up when the plan has them.", "A training stop with nothing to learn yet waits for your level. With a full quest log the card no longer flies you through the plan's later zones to \"train level 46 spells\" at 35: it keeps the pick-up in front of you and asks you to make room.", "On a zone you picked, finished quests are handed in there only if their quest giver is in that zone. The rest wait for your way back to your plan. A short zone route used to end with hand-ins in Felwood, Winterspring and Un'Goro one after another.", "With a full quest log, the card keeps the pick-up in front of you even when a quest waiting for a level, a hand-in not in your log or a dungeon quest comes before it in the plan. It used to fly you on through later zones.", "Where to? no longer counts quests you can't take there: the next part of a chain whose start you skipped or refused (the row said \"needs ... first\", and picking the zone gave an empty card), a quest you said you're not doing, or a quest red to you, in your log or not. A red quest in your log no longer makes a zone read \"continues ...\".", "Where to? updates right away when you skip a step, say you're not doing a quest, bring one back or undo.", "A quest the game showed you on offer is no longer dropped because the quest data says it needs an earlier quest you skipped.", "A training stop that waits for your level says \"Nothing to learn until level N\" on the card, and its map pin says the level instead of \"at level 0\".", "With your quest log nearly full, the card no longer plans one pick-up more than you have room for when an optional hand-in comes first.", "When nothing on your plan can be done yet (its next steps wait for a level), the card says \"Route done for now\", the level they open at, and offers your next home bases. It used to sit on a training stop reading \"Nothing to learn until level 60\".", "Visiting your trainer before a training stop's level no longer ticks that stop: you learned nothing there, and it comes back when you reach the level.", "When you level up, a quest that opens at the new level right beside you goes on the card at once, before the card sends you out of town.", "With your quest log nearly full, the quest giver the card has you visit before leaving town is one you have room for. A giver with no room left made the card send you out past another one right beside you (Auberdine).", "A gray quest in your log is off your route unless its chain leads on to a quest yellow or harder for you: the card no longer sends you to its objectives or its hand-in, adds no stop for it on the way, and the quest log check says to drop it. One that leads on stays, and the quest log check says what it leads to. The route used to keep every gray quest in your log while the quest log check said to drop it.", "Where to? no longer offers a zone for a low chain you carry there. A chain counts only when it leads to a quest yellow or harder for you: a level 57 was offered The Barrens for a level 18 quest whose next part, not on the plan, counted as worth it." } },
  { version = "1.6.4", date = "2026-11-16", items = { "Landing somewhere other than where your plan expected (the flight path you know): the quests right around you come first, instead of a long walk to the plan's next one and back.", "The card doesn't send you to another zone while your path still has quests where you are, unless that quest starts a chain for your zone (it sent a player from Riverglades to the Badlands with eight quests ready to hand in).", "Before the card sends you out of town, it has you pick up the quests the plan takes in that town, so you work on them on the same trip (Farholde Keep sent players out for the Foreman's Crate with the quest givers beside them).", "The arrow points at the game's own quest marker for an objective whose place the quest data doesn't have, instead of disappearing.", "Dead: the card no longer changes as your ghost runs past quest givers; it picks up again once you're alive.", "Your place in the plan only moves forward. A quest you take up again from a part you passed no longer pulls the card, its Base and the zones ahead back to an old zone; it is offered when you are near it.", "A side quest or a quest from earlier in the plan is never filed into the part of the plan you passed (one sent a player back to Wetlands).", "Time is priced at Forever's real pace for your level, not a fixed level an hour: what a trip is worth, whether a leftover is worth it, whether to hand in now.", "A finished quest's hand-in, side quests' too, is weighed by the XP it would lose by waiting; while you farm the card's own pick, it stays on the card.", "The quest log check uses the same \"gray\" as the route, and no longer says \"on your route\" for a quest the route skipped.", "Fixed: training, hearthing or a flight path could be ticked from the step you were looking at in the route list.", "A flag on the card: if something looks wrong, click it and send /fr report - your report then shows us exactly what happened." } },
  { version = "1.6.3", date = "2026-11-15", items = { "The Drowned City: inside, the card shows its quests from your log (Shady Saltseers, The Saltseer Captain, Ancient Gurubashi Secrets) instead of your next step outside.", "Joining your plan partway into a zone no longer drops that zone's earlier quests: anything there at your level stays on your route (half of Riverglades - Gnoll Infestation, Bats in the Belfry - was left out, and the card jumped between them as you walked).", "In a town the card keeps its stop until you do it, instead of switching sides as you walk through; a hand-in jumps the queue only when you are at its NPC.", "Collapsing the card hides everything under it (reminders, Zones, Change home base and the next-zone line stayed).", "A quest behind you that the card picked up stays on the card while you walk on, and says what it pays (\"+2.4k XP\") instead of a time it doesn't save." } },
  { version = "1.6.2", date = "2026-11-15", items = { "New options window: tabs down the side (General, Auto, Map, Size, News, Help) instead of one long list, short labels, a Reset tab link on each, and a search box that finds any option (\"food\", \"arrow\", \"scale\").", "Turn each card line on or off: step notes, the next-zone line, zone suggestions, quest items in your bags, and the reminders (bags full, Well Fed food, warlock grimoires). Or pick a look in one click: Full, Compact or Minimal.", "What's new lives in the options now: the newest version open, older ones one line each, new ones marked. Turn off the bar after updates if you like.", "Reset positions puts the card, arrow and Target button back; Help has the main commands and \"Bring back skipped steps\"." } },
  { version = "1.6.1", date = "2026-11-15", items = { "A quest you finish early no longer waits for your plan to pass its hand-in levels later, gray by then: when going now is worth more than what waiting would lose, it is your next stop.", "\"Do it now\" on a hand-in nearby: the card's Base count and the zones ahead stay on your plan while you hand it in (they showed the far part of the plan the hand-in was filed under), and the card goes back to your plan after." } },
  { version = "1.6.0", date = "2026-11-15", items = { "Every built-in plan rebuilt on the latest quest data (QuestieDB 1.1.1: 21 new quests, 296 corrected). Each was played from 1 to 60 by the simulated player and by one hopping between zones before it shipped.", "Your home base: the zone you work from, and the card always says which (\"Base: Stranglethorn\"). On your plan it is the plan's zone; \"Change home base\" on the card opens Where to? to pick another. It brings along the quests you already carry there. Near its end the card tells you once how much XP is left and the next bases; when nothing is left but quests that open later (\"2 quests here open at 40\"), it lists your next home bases to click. \"Back to plan\" takes you back to your plan, wherever you are.", "Finishing an objective, taking or handing in a quest, levelling up or entering a zone costs much less again: the addon reads your quest log once per change instead of asking the game about every quest on your route, and remembers how far your plan is done.", "When the card puts a stop before your plan's next one, it says so in a few words and what it saves (\"while you're here · saves ~3 min\"); hover it for the whole reason and your plan's next step.", "Where to? says how far each zone is (\"6 min away\") and ranks zones by the XP an hour they give you counting the trip there, so a big zone two continents away no longer beats the one next door.", "No more trips across the world for the one quest you left of a zone: when you did the rest ahead of your plan or dropped them, a far, poorly paying leftover that nothing later needs is skipped (/fr undo brings it back).", "The card no longer flicks to your plan's step and then to a better stop a moment later: it waits for the better stop (a fraction of a second) and changes once.", "A chain start added to a zone you picked says what it costs and opens (\"+4 min, opens ~12k XP\"), and \"skip chain start\" on the card takes it off for good.", "The travel line is shorter: \"Run to Stranglethorn Vale via Duskwood\" instead of every border crossed, and \"2 quests there: ...\" under it.", "A quest new in Forever shows a small \"Forever Quest\" tag (hover it for what that means) instead of three lines of text.", "The \"won't do\" link stays on the card while you hover it.", "No more gear-repair reminder: other addons do that. The bags-full one stays.", "Clicking the step you are on in the card's list takes you back to it (as in the route window) instead of \"just looking\" at it.", "\"N won't do\" on the card is \"N off-route\" now, and the card's notes are shorter and plainer.", "A finished home base shows \"Carry on\" right away, and nothing on the card offers to save and replan on a flight any more.", "The quest log check only suggests dropping gray quests and ones you said you won't do. A quest another zone has is marked yours, with Go to make that zone your home base; anything else off your route is yours to keep. Abandoning asks first and says it also leaves your route.", "Dead: the map no longer draws your step's trail from somewhere else while you run back to your corpse." } },
  { version = "1.5.2", date = "2026-11-15", items = { "No more hitch every few steps while you walk or ride: working out your next stop now runs in the background, a sliver of each frame, instead of all at once (the worst frame walking went from about 30 ms to under 2).", "Finishing an objective, taking or handing in a quest, levelling up or entering a new zone costs about half as much as before: one route update per change instead of up to three, and the next stop worked out in the background. The card shows your plan's step at once and moves only if a better stop turns up a moment later.", "The quest log check and the log bookkeeping no longer walk your whole route on every change." } },
  { version = "1.5.1", date = "2026-11-14", items = { "No more frame drops when you kill a quest mob or loot a quest item: a count moving (\"Gnoll Paws: 3/8\") now only updates the card's counts instead of re-planning your whole route each time, and quests you haven't handed in are looked up once instead of on every update.", "The built-in plans download is less than half the size (about 15 MB per faction, was 38): the steps every plan of a faction shares are kept once and put back for your plan when it loads." } },
  { version = "1.5.0", date = "2026-11-14", items = { "Pick a zone whose quests need an earlier part you haven't done, and those steps come first, cut from your own plan, when they're close by. When they aren't, the card says what was left out and what it needs.", "\"Planned route\" goes back to where your plan still has quests for you, however much you wandered, not to where you left it.", "A zone row's tooltip shows the chain behind it: how far you are, the XP left in it, where it goes on and when it turns gray. If it needs a chain start, it says how much more XP doing that first would open up there.", "Going elsewhere, the tooltip warns when a chain you carry is about to turn gray.", "Picking a zone no longer replaces your plan's zones with that one zone: the companion's replan kept treating the zone you picked as your whole path.", "\"Where to?\" is in the route window for everyone, not only with the companion, and offers many more zones: the built-in plans now carry a ready route for every zone worth going to at your level (Alliance 64, Horde 69, was 45 and 47).", "Each zone shows the XP it has for you and the level that gets you to (\"~71k XP · to 36.4\"), and the header how much you need for your next level.", "A quest picked up in a capital on the way is no longer shown as the zone you go to: Desolace, \"pick up Reclaimers' Business in Ironforge first\". A zone whose route is all in another zone is listed once (Shen'dralas and Desolace).", "A zone whose route also works a neighbour says so: \"Hillsbrad + Alterac\" (Alterac's quests are given in Southshore, so it never had a route of its own).", "\"Not now\" on a stop the card pulled forward (a trainer, a hand-in while you're here) holds: it came straight back when a stop was added before it.", "Inside a dungeon and after leaving one, quest titles from before no longer float over the card.", "Picking a zone: the zone you picked says YOUR PICK, \"Planned route\" points where your plan was going before you left it, and the Plan tab shows your plan ahead from there. A zone with no route yet does nothing when clicked.", "The card names its zone once (\"OUT IN REDRIDGE\"), and its \"Next zone\" line agrees with Where to?. A finished zone says what's next on your plan.", "A chain you carry that is about to turn gray is named at the bottom of Where to?.", "No more wording about a planner or \"Path 1 of 3\" for the built-in plans; no side-trip offer inside a dungeon.", "The card no longer jumps between two next steps as you walk: a quest added to your route (one you finished early) no longer throws off which step it is on, a quest you abandoned once a later part of its chain was handed in is no longer offered again, and nothing on another continent comes first.", "The arrow: beside a long straight path it points the way the path goes instead of back onto it first, and it follows the step the card shows after a stop is added.", "The route window no longer makes the game stutter on a flight or when you scroll it.", "Side trips read as side trips (\"Side trip: Felhunter\"), the card names its zone once, and its buttons and the \"won't do\" link no longer overlap.", "Built-in plans rebuilt with the data for all this; the plans download grew by about 0.3 MB." } },
  { version = "1.4.10", date = "2026-11-14", items = { "\"Where to?\" has two tabs on a rail at its left. Zones lists the zones you could go to now, one row each: about how much XP is left there for you (and what share of your level that is), the quests you can still do there, and one reason - hand-ins waiting, a quest you carry there, or a quest it needs you to do first (and where). The XP counts what you could do there before you run out and have to move on: follow-ups once their first part is done, quests that open as you level, not ones you would outlevel first. Your plan's next zone is marked PLANNED NEXT.", "Plan shows the zones ahead on your plan with their quests. The companion's other full plans fold under it.", "On a zone you picked, a quest whose earlier part you haven't done waits instead of sending you to a giver with nothing for you, and \"Planned route\" picks up where you left your plan.", "When a zone you picked is done, the card offers \"Carry on\" to where your plan picks up.", "The window keeps its size and scrolls; hovering a row or tab says what it does.", "Plans name each part after the zone its quests are in (a stretch planned from Shen'dralas but all in Desolace now reads Desolace), and long chains whose items the quest data doesn't place are kept (Linken's chain in Un'Goro)." } },
  { version = "1.4.9", date = "2026-11-14", items = { "New built-in plans for every race and class. Each race starts on its own, then all of a faction's races share one main route from about level 21: no grinding anywhere from 1 to 60 (the old plans had 50 to 150 hours of it). Every plan was played from 1 to 60 by the simulated player first.", "Horde Skyborne (Windshaper) have built-in plans now: druid, hunter, rogue, shaman and warrior.", "Pick your zone: the route window lists the zones that fit your level with their XP per hour. Click one and the card takes you there, with the pick-ups on the way. No companion app needed.", "On a zone you picked, \"Change zone\" on the card opens the zone list, and its first button is your planned route, where it picks up at your level. When a zone is done, the card says so and opens the list.", "Plans keep the quests you carry instead of telling you to drop them, and long chains run to the end (The Missing Diplomat now reaches Jaina).", "A quest the giver didn't offer no longer flips on and off your route while the world map shows it somewhere else.", "Stormwind shows as one zone in the route list, not as both Stormwind and Stormwind City." } },
  { version = "1.4.8", date = "2026-11-13", items = { "Quests started by an item (a page, a head, a strange object) are offered on the card when the item is in your bags: \"use it\" with the use-item button above the card, or the X if you won't do it.", "On a flight the card holds the step you took off with until you land; it no longer re-picks as you pass over other zones.", "A quest that needs a profession rank or reputation you don't have yet (Goblin Engineering needs Engineering 200) is left off your route, instead of walking you to a giver who has nothing for you. It comes back once you have it.", "Faster: the card refreshes about twice as fast, and working out a trip (walk, fly, boat, hearth) about ten times as fast. Picks and directions are the same." } },
  { version = "1.4.7", date = "2026-11-13", items = { "Flying is time you can look away; walking isn't. A trip that flies and walks a little now wins over walking the whole way when it's about as quick: the card says \"about as quick as walking, and N min less on foot\".", "The card's footer says where the plan goes next: \"Next zone: Duskwood, after 4 quests here\" (it said \"planned for level 33 · plan goes to level 43\").", "The route list's header reads \"To level 43 · about 38 h left · 26 of 893 steps done\"; when the plan was made is in its tooltip.", "\"Not doing this quest\" and \"the giver doesn't offer it\" are small buttons (a red X, a struck-out !) with tooltips, beside Map, instead of two lines of text.", "Map opens the world map where the step is - for a trip, where it takes you - and its pin flashes once the map shows it.", "The \"N won't do\" link stays put while you hover the card (it moved away under the mouse).", "Quests with the same name and different givers are alternatives: once you've taken one, the others leave your route.", "The next step weighs going now against coming back later with the real trip, so a stop it fits in is one that's worth it.", "Plans from the companion app: far less grinding (a quest that pays better than grinding is never dropped as \"too many kills\" or \"annoying\"), quests up to 3 levels above you from level 20, chains that run through several zones are followed (The Tower of Althalaxx), quests whose work is in another zone are picked up and carried, and walking lines go round the other faction's towns." } },
  { version = "1.4.6", date = "2026-11-13", items = { "Arrived somewhere the plan comes back to later (you hearthed to Stormwind, flew into a town): if all of that later visit can be done now, it's done now and the trip back is dropped - \"the plan comes back here for this later\".", "Already where your plan goes after its next trip (you flew on ahead, or rode there yourself): the card starts on the plan's quests where you are, and the trip waits.", "A pick-up is never offered before the quest that leads to it is handed in, whatever the plan says (For Further Study without Gleaning Our Future).", "Plans made with quests already finished in your log no longer fly you back and forth to their givers.", "A step that needs a flight, a boat or your hearthstone reads \"Travel to Wetlands\", with the step itself under it.", "The arrow: on the Deeprun Tram it says to ride it; riding to a flight master it aims at him once you're past the trip's first waypoint (Theramore); a ride aims at the border, not a flight master the road passes; a line that loops back past you can't pull it backwards; after you die it points to your corpse.", "Turtle Meat and similar: \"A few in Hillsbrad Foothills too - the plan farms the bigger group in Alterac Mountains\".", "Horde: the zone-choice prompt knows every capital, and warlocks get the grimoire errand in Orgrimmar and the Undercity.", "A dungeon or class route you didn't pick is never where a new plan puts you (a plan with no leveling path put a player on Gnomeregan).", "A flight-path step ticks only for its own flight point, not another in the same zone; automatic ticks no longer count as \"ticked by hand\".", "The other faction's towns are named (Southshore, Refuge Pointe - not \"Darla Harris's town\").", "\"Save & replan\" on a flight only shows when the companion app plans for you. The route list's zone chips show names only.", "Quest data: QuestieDB 1.1.0." } },
  { version = "1.4.5", date = "2026-11-13", items = { "A zone change says why: \"Going to Alterac Mountains for 2 quests (Soothing Turtle Bisque, Alterac Granite), then Hillsbrad Foothills\" on the card, above how to get there.", "Zones ahead: a small panel beside the card (the tab on its edge) lists where the route goes next and how many quests in each. The route list's zone chips start from where you are, not from level 1.", "A Target button for each mob a step names (Snapjaw and Cranky Benj both drop Turtle Meat), stacked with the first; Ctrl+drag the top one to move them together.", "Clicking Map makes the step's pin blink on the world map, and our pins sit on top of the map's own markers.", "The arrival ring pulses three times and stops, instead of the whole time you're there.", "\"Quests you won't do\" is a small link in the card's footer, not a row of its own. The footer reads \"planned for level 29 · plan goes to level 60\".", "Fixed: the Target button clicked or dragged in combat raised a \"blocked action\" error." } },
  { version = "1.4.4", date = "2026-11-12", items = { "A trip with an extra change (a boat, the tram, a portal) has to save real time to win: Refuge Pointe to Stormwind is the flight to Stormwind again, not a flight to Ironforge and the tram for 3 seconds less. The walk off the tram no longer reads \"from Stormwind to Stormwind\".", "\"Not now\" on the card for a stop the route fitted in from where you are (a hand-in while you're here, a quest just behind you): it goes back to the plan's next step, and offers the stop again once you've moved on.", "Every built-in plan rebuilt with each quest's expected time to do, so the next step weighs a quick quest nearby against a long one properly; each plan played from 1 to 60 by simulated players, none broke a check." } },
  { version = "1.4.3", date = "2026-11-12", items = { "No more walking over the mountains from Dun Morogh into the Wetlands: the way there is through Loch Modan and Dun Algaz, and the arrow takes it.", "The Dalaran portal to Stormwind is one way: trips no longer count on a portal from the Mage Tower to Dalaran.", "Quest items in your bank (a rested-XP stash, or put there yourself): the card says to take them out, since the quest only counts what's in your bags.", "Setting your hearthstone at the plan's inn is recognised, so the route stops asking you to do it again.", "Hover a step in the list to see why it isn't the next one yet." } },
  { version = "1.4.2", date = "2026-11-12", items = { "New option: take the flight your route needs when you talk to a flight master (Options, off by default; hold Shift to choose yourself).", "What to do next is now worked out from where you are: the plan's next steps in the order that makes the whole way shortest, and finished quests whose hand-in is close by (\"while you're here\"). Back in town to sell or to group up, the town's hand-ins come first; a hand-in across the world is left for when the route passes it. The card says why when it leaves the plan's order. (Options: \"Choose the next step from where I am\".)", "Bags nearly full (or gear wearing out): the vendor visit is fitted into your way where it costs least, and the errand line says which vendor and when. A quest below you stays on your route while its chain leads to quests still worth XP.", "The hub hand-in run: out in the field, a finished quest waits for the town the route returns to (unless its chain goes on right there), so you quest a good while and then hand in a pile at once - and the card names the run: \"Hand-in run here: 6 quests, about 8,400 XP\". Plans hold at most 30 quests, leaving 10 slots of your log for dungeon quests and anything else you pick up.", "Long quest chains are valued as a whole when plans are made, so their first parts aren't cut; a trip to a capital has to be worth it.", "Joining the built-in plan partway: quests right next to you that still give XP are offered instead of being skipped as \"behind you\", and a quest worth XP close by comes before a grind step.", "Quests count as gray by the game's own line (5 levels below you early on, more later): a level 7 is no longer sent to a level 1 quest.", "A quest its giver turns down at two different levels stays off your route; once, it's tried again a level on (Forever asks more than the quest data for some). No more \"your path was switched\" message when you've just finished a zone.", "Every built-in plan rebuilt with the planner fixes below, and each one played from 1 to 60 by simulated players.", "NPCs Forever renamed are found by their Forever names (Corma Villard, Velarok Windblade, and two more): the Target key and the quest checks missed them.", "Steps say what the quest asks: The Missing Diplomat's fight with Tapoke Jahn said \"Speak with\", and some kill quests read \"Speak with Mottled Boar\". The escort tips are only on real escorts.", "Quests handed in at a chest or object in town (The Lost Ingots chain in Menethil) are on the route.", "Quests for Forever's new dungeons stay in the dungeon: Horrors in the Highland (Excavation Site: Wetlands) was a step outside, as if its boss were in Menethil.", "No more \"hand it in\" right after picking up a quest whose work the quest data doesn't describe (Brewer's Trade in Southshore, and about 90 others): one that leads to a follow-up stays on your route with a \"do the work\" step that says to follow your quest log, and An Alarming Request is handed in near Dalaran, not in Southshore." } },
  { version = "1.4.1", date = "2026-11-11", items = { "The arrow points the way instead of herding you onto the dotted line: step off it and the line is redrawn from where you are, it looks further ahead along straight stretches, and roads only win when they're nearly on the way.", "Forever Route Targeting now really marks the NPC with a star (it was blocked by the game).", "Logging out is quick again: a timing check rebuilt the route ten times at logout and ran past the game's limit on long plans. The options window opens on screen again.", "A quest its giver turned down once you had the level for it stays off your route, instead of coming back every level.", "Hearth steps only when the game says you're bound there and the hearthstone is ready.", "Good quests nearby that the plan can't hold (giver in a city, objectives elsewhere, or work the quest data doesn't describe, like Brewer's Trade) are offered when you're at the giver.", "The quest log check lists quest items in your bags that are safe to delete.", "The Target button floats just above the card; /fr target reset puts it back. \"Not doing this quest\" no longer covers the title.", "Your path stays put when a new plan arrives, and a switch is announced in chat (/fr paths).", "No more stray path flashing on the map." } },
  { version = "1.4.0", date = "2026-11-11", items = { "Horde: built-in plans for every Horde race and class.", "Every Alliance plan rebuilt: through Forever's new zones (Riverglades, Shen'dralas), grinding a level where the quests run out instead of sending you into dungeons.", "The built-in plans are two addons, one per faction, instead of one per race and class (a much shorter addon list).", "The arrow aims a little ahead along the path, so it no longer swings at every corner.", "Walking paths follow the roads and keep away from hostile camps (Elwynn Forest, the Wetlands so far).", "The Forever Route scale slider applies when you let go (it used to jump to its end while dragging); the card can no longer end up off the screen (/fr card reset brings it back)." } },
  { version = "1.3.2", date = "2026-11-11", items = { "The Target button stays on the card in combat.", "Built-in plans are grouped under Forever Route in the addon list.", "Scrollbars in the route list and the quest log check can be dragged and clicked.", "Option: accept route quests and hand in finished ones automatically (not when there's a reward to choose; hold Shift to skip). Off by default.", "The card no longer fades in combat by default (an option if you liked it).", "One Forever Route scale for the card, arrow, route list and every window (/fr options or /fr scale); on screens where our text is small (e.g. 4K with ElvUI), a bar offers a bigger size. Clearer grey text.", "Smaller saved files: without the companion app, walking trails and learning data aren't recorded (only the companion uses them) and old ones are cleared. /fr storage shows what's kept.", "A long walk inside a zone can become a flight: when a flight path you know lands clearly nearer the spot (Darkshire to Sven's camp by way of Sentinel Hill), the card and the arrow send you to the flight master first.", "Flight points now come from Forever's own flight tables: Mount Hyjal's Tainted Foothills added, both Hyjal points for the Horde too, the Riverglades flight masters at their real spots. Knowing one flight path of a zone no longer counts as knowing its other one." } },
  { version = "1.3.1", date = "2026-11-11", items = { "The Target button sits with the card instead of over every window (the character sheet covers it now).", "Ctrl+drag the Target button anywhere; /fr target reset puts it back.", "What's new: resizable, and \"Older versions\" shows earlier notes." } },
  { version = "1.3.0", date = "2026-11-11", items = { "Starting at any level: the built-in plan picks up where you are, choosing the best nearby part of the plan for your level.", "No more far-away stops (like another zone's flight path) put in front of you.", "In a dungeon, the card shows your quests for it with live progress, and which ones you could have picked up.", "Quest log full: the card goes to hand-ins and objectives first; pick-ups wait until there's room.", "New key: Keybindings > AddOns > \"Forever Route Targeting\" targets the step's NPC and marks it with a star.", "/fr report: copy an anonymous bug report to paste to us.", "What's new: after an update, a bar under the card links to these notes (/fr news any time).", "\"Run to\" until you can ride. Card scale up to 2.0, arrow up to 2.5.", "Correction: 1.2.1's flight path pickup doesn't work on Forever's client; the card now asks you to open any flight master's map once." } },
  { version = "1.2.1", date = "2026-11-11", items = { "Map dots behind you now disappear.", "No more \"Error loading ForeverRoute/Route.lua\" warning.", "Travel for Riverglades, Shen'dralas and Mount Hyjal." } },
  { version = "1.2.0", date = "2026-11-10", items = { "Calmer card: kill and loot steps take over only when they count; finished quests nearby are offered.", "\"Won't do\" quests come back if you finish them anyway.", "Route list follows you; minimap shows one pin; greyed world-map pins say why.", "Walking line along the ground in Stormwind, Elwynn and the Wetlands.", "QuestieDB 1.0.14. Elite quests and dungeons are never forced." } },
  { version = "1.1.1", date = "2026-11-10", items = { "Finished quests with their NPC nearby come first." } },
  { version = "1.1.0", date = "2026-11-10", items = { "First release: 1-60 routes for every Alliance race and class." } },
}
